CREATE OR REPLACE FUNCTION public.cleanup_tenant(p_tenant_id text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
        DECLARE
          total INTEGER := 0;
          tbl TEXT;
          deleted INTEGER;
        BEGIN
          FOREACH tbl IN ARRAY ARRAY[
            'AjusteBancario'::text, 'Almacen'::text, 'Anticipo'::text, 'Categoria'::text, 'CierreContable'::text, 'Cliente'::text, 'CompraDocumento'::text, 'CompraDocumentoItem'::text, 'CompraProducto'::text, 'CompraServicio'::text, 'Contrato'::text, 'CuentaBancaria'::text, 'CuentaPorCobrar'::text, 'CuentaPorPagar'::text, 'DefectacionCatalogo'::text, 'DeudaCash'::text, 'Empleado'::text, 'EquipoReparacion'::text, 'GastoCompra'::text, 'GastosDE'::text, 'ListaPrecio'::text, 'Merma'::text, 'MiEmpresa'::text, 'Oferta'::text, 'OrdenProduccion'::text, 'OrdenProduccionHistorial'::text, 'OrdenReparacion'::text, 'OrdenReparacionEquipo'::text, 'OrdenReparacionItem'::text, 'OrdenReparacionMaterial'::text, 'PagoCuentaPorPagar'::text, 'Pagosalario'::text, 'PiezaReparacion'::text, 'PrestamoCash'::text, 'Producto'::text, 'PuntoDeVenta'::text, 'Receta'::text, 'RecetaIngrediente'::text, 'ReconciliacionGasto'::text, 'ReconciliacionServicio'::text, 'ReconciliacionVenta'::text, 'Servicios'::text, 'StockUbicacion'::text, 'Transferencia'::text, 'TransferenciaBancaria'::text, 'Unidad'::text, 'ValeSalida'::text, 'ValeSalidaItem'::text, 'Vendor'::text, 'Venta'::text, 'VentaServicios'::text, 'apertura_periodos'::text, 'arqueos_caja'::text, 'auditoria_periodos'::text, 'backup_logs'::text, 'backup_plans'::text, 'facturas'::text, 'periodos_contables'::text, 'purchase_allocations'::text, 'review_prompts'::text, 'reviews'::text, 'series_facturacion'::text, 'tenant_licenses'::text, 'tenant_memberships'::text, 'turnos_punto_venta'::text
          ]
          LOOP
            EXECUTE format('DELETE FROM %I WHERE "tenantId" = $1', tbl)
              USING p_tenant_id;
            GET DIAGNOSTICS deleted = ROW_COUNT;
            total := total + deleted;
          END LOOP;
          DELETE FROM tenants WHERE "tenantId" = p_tenant_id;
          GET DIAGNOSTICS deleted = ROW_COUNT;
          total := total + deleted;
          RETURN total;
        END;
        $function$

CREATE OR REPLACE FUNCTION public.guard_apertura_revision_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."estado" <> 'BORRADOR' THEN
      RAISE EXCEPTION 'opening revisions must be created as drafts';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'opening revisions are append-only';
  END IF;

  IF NEW."revisionId" IS DISTINCT FROM OLD."revisionId"
    OR NEW."aperturaId" IS DISTINCT FROM OLD."aperturaId"
    OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
    OR NEW."periodoId" IS DISTINCT FROM OLD."periodoId"
    OR NEW."version" IS DISTINCT FROM OLD."version"
    OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN
    RAISE EXCEPTION 'opening revision identity is immutable';
  END IF;

  IF OLD."estado" = 'BORRADOR' AND NEW."estado" = 'BORRADOR' THEN
    RETURN NEW;
  END IF;

  IF OLD."estado" = 'BORRADOR' AND NEW."estado" = 'PRESENTADA' THEN
    IF NEW."revisadaPor" IS NOT NULL OR NEW."revisadaAt" IS NOT NULL THEN
      RAISE EXCEPTION 'draft presentation cannot include reviewer fields';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD."estado" = 'PRESENTADA' AND NEW."estado" IN ('APROBADA', 'RETIRADA') THEN
    IF NEW."presentadaPor" IS DISTINCT FROM OLD."presentadaPor"
      OR NEW."presentadaAt" IS DISTINCT FROM OLD."presentadaAt"
      OR NEW."digestVersion" IS DISTINCT FROM OLD."digestVersion"
      OR NEW."digestSha256" IS DISTINCT FROM OLD."digestSha256"
      OR NEW."evidenciaVersion" IS DISTINCT FROM OLD."evidenciaVersion"
      OR NEW."evidenciaSha256" IS DISTINCT FROM OLD."evidenciaSha256" THEN
      RAISE EXCEPTION 'submitted opening evidence digest is immutable';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'invalid opening revision lifecycle transition: % -> %', OLD."estado", NEW."estado";
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_apertura_revision_lines()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  revision_status TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT "estado" INTO revision_status FROM "apertura_revisiones"
      WHERE "tenantId" = NEW."tenantId" AND "periodoId" = NEW."periodoId"
        AND "aperturaId" = NEW."aperturaId" AND "revisionId" = NEW."revisionId"
      FOR UPDATE;
  ELSE
    SELECT "estado" INTO revision_status FROM "apertura_revisiones"
      WHERE "tenantId" = OLD."tenantId" AND "periodoId" = OLD."periodoId"
        AND "aperturaId" = OLD."aperturaId" AND "revisionId" = OLD."revisionId"
      FOR UPDATE;
  END IF;

  IF revision_status IS DISTINCT FROM 'BORRADOR' THEN
    RAISE EXCEPTION 'submitted opening revision evidence lines are immutable';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW."lineaId" IS DISTINCT FROM OLD."lineaId"
    OR NEW."aperturaId" IS DISTINCT FROM OLD."aperturaId"
    OR NEW."revisionId" IS DISTINCT FROM OLD."revisionId"
    OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
    OR NEW."periodoId" IS DISTINCT FROM OLD."periodoId"
  ) THEN
    RAISE EXCEPTION 'opening line revision identity is immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_approved_financial_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND OLD."status" = 'APPROVED' THEN
    RAISE EXCEPTION 'approved financial snapshots are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD."status" = 'APPROVED' THEN
    RAISE EXCEPTION 'approved financial snapshots are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW."status" = 'APPROVED' AND (
    NEW."schemaVersion" IS DISTINCT FROM 3
    OR NEW."approvedAt" IS NULL
    OR NEW."approvedBy" IS NULL
    OR NEW."resumenJson" IS NULL
    OR NEW."hashIntegridad" IS NULL
  ) THEN
    RAISE EXCEPTION 'approved v3 snapshots require final evidence and approval metadata'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_used_functional_currency_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW."functionalCurrencyCode" IS DISTINCT FROM OLD."functionalCurrencyCode" AND (
    EXISTS (
      SELECT 1 FROM "financial_auxiliary_checkpoints" c
      WHERE c."tenantId" = OLD."tenantId"
    ) OR EXISTS (
      SELECT 1 FROM "snapshot_periodos" s
      JOIN "periodos_contables" p ON p."periodoId" = s."periodoId"
      WHERE p."tenantId" = OLD."tenantId" AND p."estado" = 'APROBADO'
    ) OR EXISTS (
      SELECT 1 FROM "ReconciliacionVenta" r
      WHERE r."tenantId" = OLD."tenantId" AND r."fxEvidenceVersion" = 1
    ) OR EXISTS (
      SELECT 1 FROM "ReconciliacionServicio" r
      WHERE r."tenantId" = OLD."tenantId" AND r."fxEvidenceVersion" = 1
    ) OR EXISTS (
      SELECT 1 FROM "ReconciliacionGasto" r
      WHERE r."tenantId" = OLD."tenantId" AND r."fxEvidenceVersion" = 1
    )
  ) THEN
    RAISE EXCEPTION 'functional currency is immutable after accounting evidence exists'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
